def solve(operation, digest, receipt, authorized, provider_dedup):
    if not isinstance(receipt, (list, tuple)) or len(receipt) != 3:
        raise ValueError("invalid receipt")
    status, key, payload = receipt
    if status == "committed":
        if not isinstance(key, str) or not isinstance(payload, str):
            raise ValueError("missing receipt binding")
        return ("commit" if (key, payload) == (operation, digest) else "conflict", operation)
    if status not in ("absent", "unknown") or key is not None or payload is not None:
        raise ValueError("invalid receipt")
    return ("retry" if authorized and (status == "absent" or provider_dedup) else "pause", operation)
